CREATE TYPE public.app_role AS ENUM ('talent','employer','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', title text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', experience integer NOT NULL DEFAULT 0 CHECK(experience >= 0), education text NOT NULL DEFAULT '', languages text NOT NULL DEFAULT '', interests text NOT NULL DEFAULT '', preferences text NOT NULL DEFAULT '', shared boolean NOT NULL DEFAULT false, passport_ref uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; GRANT SELECT ON public.profiles TO anon;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY roles_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_read ON public.profiles FOR SELECT USING(shared OR id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.new_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,CASE WHEN NEW.raw_user_meta_data->>'account_type'='employer' THEN 'employer'::public.app_role ELSE 'talent'::public.app_role END); RETURN NEW; END $$;
CREATE TRIGGER talentbridge_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.new_profile();
CREATE TABLE public.opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employer_id uuid REFERENCES public.profiles(id), company text NOT NULL,title text NOT NULL,location text NOT NULL,type text NOT NULL DEFAULT 'Full-time',skills text[] NOT NULL DEFAULT '{}',experience integer NOT NULL DEFAULT 0,description text NOT NULL,deadline date NOT NULL,status text NOT NULL DEFAULT 'published' CHECK(status IN ('published','pending','rejected','closed')),demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.opportunities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.opportunities TO authenticated; GRANT ALL ON public.opportunities TO service_role; ALTER TABLE public.opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY jobs_read ON public.opportunities FOR SELECT USING(status='published' OR employer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY jobs_insert ON public.opportunities FOR INSERT TO authenticated WITH CHECK(employer_id=auth.uid() AND public.has_role(auth.uid(),'employer') AND NOT demo AND status='published');
CREATE POLICY jobs_update ON public.opportunities FOR UPDATE TO authenticated USING((employer_id=auth.uid() AND NOT demo) OR public.has_role(auth.uid(),'admin')) WITH CHECK((employer_id=auth.uid() AND NOT demo) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),talent_id uuid NOT NULL REFERENCES public.profiles(id),opportunity_id uuid NOT NULL REFERENCES public.opportunities(id),cover_note text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Shortlisted','Interview','Rejected','Hired')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(talent_id,opportunity_id));
GRANT SELECT,INSERT,UPDATE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role; ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY applications_read ON public.applications FOR SELECT TO authenticated USING(talent_id=auth.uid() OR EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.employer_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY applications_insert ON public.applications FOR INSERT TO authenticated WITH CHECK(talent_id=auth.uid() AND public.has_role(auth.uid(),'talent') AND status='Submitted' AND EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.status='published' AND o.deadline>=current_date AND NOT o.demo));
CREATE POLICY applications_update ON public.applications FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.employer_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY employer_applicant_read ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.applications a JOIN public.opportunities o ON o.id=a.opportunity_id WHERE a.talent_id=profiles.id AND o.employer_id=auth.uid()));
CREATE TABLE public.saved_opportunities(user_id uuid NOT NULL REFERENCES public.profiles(id),opportunity_id uuid NOT NULL REFERENCES public.opportunities(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,opportunity_id)); GRANT SELECT,INSERT,DELETE ON public.saved_opportunities TO authenticated; GRANT ALL ON public.saved_opportunities TO service_role; ALTER TABLE public.saved_opportunities ENABLE ROW LEVEL SECURITY; CREATE POLICY saves_own ON public.saved_opportunities FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.assessments(id text PRIMARY KEY,title text NOT NULL,category text NOT NULL,questions jsonb NOT NULL); GRANT SELECT ON public.assessments TO anon,authenticated; GRANT ALL ON public.assessments TO service_role; ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY; CREATE POLICY assessments_read ON public.assessments FOR SELECT USING(true);
CREATE TABLE public.assessment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),assessment_id text NOT NULL REFERENCES public.assessments(id),score integer NOT NULL CHECK(score BETWEEN 0 AND 100),answers jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.assessment_attempts TO authenticated; GRANT ALL ON public.assessment_attempts TO service_role; ALTER TABLE public.assessment_attempts ENABLE ROW LEVEL SECURITY; CREATE POLICY attempts_own ON public.assessment_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.submit_assessment(assessment text, responses jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE qs jsonb; result integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT questions INTO qs FROM public.assessments WHERE id=assessment; IF qs IS NULL OR jsonb_array_length(responses)<>jsonb_array_length(qs) THEN RAISE EXCEPTION 'Answer every question'; END IF; SELECT round(100.0*count(*) FILTER(WHERE (responses->>(ord-1)::integer)::integer=(q->>'correct')::integer)/count(*)) INTO result FROM jsonb_array_elements(qs) WITH ORDINALITY AS t(q,ord); INSERT INTO public.assessment_attempts(user_id,assessment_id,score,answers) VALUES(auth.uid(),assessment,result,responses); RETURN result; END $$;
CREATE TABLE public.mentors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,title text NOT NULL,expertise text[] NOT NULL,availability text NOT NULL,demo boolean NOT NULL DEFAULT true); GRANT SELECT ON public.mentors TO anon,authenticated; GRANT ALL ON public.mentors TO service_role; ALTER TABLE public.mentors ENABLE ROW LEVEL SECURITY; CREATE POLICY mentors_read ON public.mentors FOR SELECT USING(true);
CREATE TABLE public.mentorship_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),mentor_id uuid NOT NULL REFERENCES public.mentors(id),message text NOT NULL,status text NOT NULL DEFAULT 'Pending',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.mentorship_requests TO authenticated; GRANT ALL ON public.mentorship_requests TO service_role; ALTER TABLE public.mentorship_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY requests_own ON public.mentorship_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY requests_insert ON public.mentorship_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.mentors WHERE id=mentor_id AND demo));
CREATE TABLE public.readiness_progress(user_id uuid NOT NULL REFERENCES public.profiles(id),task text NOT NULL,complete boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,task)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.readiness_progress TO authenticated; GRANT ALL ON public.readiness_progress TO service_role; ALTER TABLE public.readiness_progress ENABLE ROW LEVEL SECURITY; CREATE POLICY readiness_own ON public.readiness_progress FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),name text NOT NULL,path text NOT NULL,status text NOT NULL DEFAULT 'Pending review' CHECK(status IN ('Pending review','Reviewed by platform administrator','Rejected')),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.credentials TO authenticated; GRANT ALL ON public.credentials TO service_role; ALTER TABLE public.credentials ENABLE ROW LEVEL SECURITY; CREATE POLICY credential_read ON public.credentials FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY credential_insert ON public.credentials FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Pending review');
CREATE TABLE public.credential_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),credential_id uuid NOT NULL REFERENCES public.credentials(id),reviewer_id uuid NOT NULL REFERENCES public.profiles(id),decision text NOT NULL,notes text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.credential_reviews TO authenticated; GRANT ALL ON public.credential_reviews TO service_role; ALTER TABLE public.credential_reviews ENABLE ROW LEVEL SECURITY; CREATE POLICY reviews_read ON public.credential_reviews FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.credentials c WHERE c.id=credential_id AND c.user_id=auth.uid())); CREATE POLICY reviews_insert ON public.credential_reviews FOR INSERT TO authenticated WITH CHECK(reviewer_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.review_credential(credential uuid, approved boolean, note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(note))<3 THEN RAISE EXCEPTION 'Review notes required'; END IF; UPDATE public.credentials SET status=CASE WHEN approved THEN 'Reviewed by platform administrator' ELSE 'Rejected' END WHERE id=credential; INSERT INTO public.credential_reviews(credential_id,reviewer_id,decision,notes) VALUES(credential,auth.uid(),CASE WHEN approved THEN 'Reviewed by platform administrator' ELSE 'Rejected' END,note); END $$;
CREATE FUNCTION public.impact_counts() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('professionals',(SELECT count(*) FROM profiles),'assessments',(SELECT count(*) FROM assessment_attempts),'passports',(SELECT count(DISTINCT user_id) FROM credentials WHERE status='Reviewed by platform administrator'),'employers',(SELECT count(*) FROM user_roles WHERE role='employer'),'opportunities',(SELECT count(*) FROM opportunities WHERE NOT demo AND status='published'),'applications',(SELECT count(*) FROM applications),'mentorships',(SELECT count(*) FROM mentorship_requests),'placements',(SELECT count(*) FROM applications WHERE status='Hired')) $$;
CREATE INDEX applications_job_idx ON public.applications(opportunity_id); CREATE INDEX attempts_user_idx ON public.assessment_attempts(user_id); CREATE INDEX jobs_employer_idx ON public.opportunities(employer_id);
