INSERT INTO public.assessments(id,title,category,questions) VALUES('ict','ICT & Software Development','Technology','[{"question":"Which HTTP method retrieves data?","options":["GET","DELETE","PATCH","POST"],"correct":0},{"question":"What does a Git commit record?","options":["A database password","A snapshot of changes","A browser cookie","A network address"],"correct":1},{"question":"Which practice improves accessibility?","options":["Removing labels","Color-only feedback","Semantic HTML","Disabling zoom"],"correct":2}]'),('digital','Digital Literacy','Digital skills','[{"question":"Which is a strong security practice?","options":["Reusing passwords","Sharing passwords","Multi-factor authentication","Ignoring updates"],"correct":2},{"question":"What is phishing?","options":["A spreadsheet formula","A deceptive request for private information","A backup method","A software license"],"correct":1},{"question":"Which tool calculates tabular data?","options":["Spreadsheet","Image viewer","Music player","Camera"],"correct":0}]'),('finance','Accounting & Finance','Finance','[{"question":"Assets equal liabilities plus what?","options":["Expenses","Equity","Revenue","Cash flow"],"correct":1},{"question":"A cash flow statement tracks what?","options":["Staff attendance","Inventory colors","Cash movements","Office size"],"correct":2},{"question":"Which is an expense?","options":["Rent paid","Owner equity","Loan received","Sales revenue"],"correct":0}]'),('business','Business Administration','Business','[{"question":"What makes a SMART goal measurable?","options":["A specific metric","An opinion","No deadline","A broad idea"],"correct":0},{"question":"What is a project milestone?","options":["A daily expense","An important progress point","A password","An invoice"],"correct":1},{"question":"Which supports effective teamwork?","options":["Unclear roles","Withholding feedback","Clear communication","No planning"],"correct":2}]'),('service','Customer Service','Professional skills','[{"question":"First response to a complaint?","options":["Ignore it","Listen and acknowledge","Blame the customer","End the conversation"],"correct":1},{"question":"What is active listening?","options":["Interrupting","Multitasking","Confirming understanding","Changing topic"],"correct":2},{"question":"An unresolved issue should be?","options":["Escalated appropriately","Deleted","Hidden","Dismissed"],"correct":0}]');